import functools
import time

def timed(func):
    @functools.wraps(func)          # preserve __name__/__doc__ of func
    def wrapper(*args, **kwargs):
        start = time.perf_counter()
        try:
            return func(*args, **kwargs)
        finally:
            elapsed = time.perf_counter() - start
            print(f"[timed] {func.__name__} took {elapsed:.4f}s")
    return wrapper

@timed
def transform(rows):
    """Uppercase a status field for each row."""
    return [{**r, "status": r["status"].upper()} for r in rows]

data = [{"id": 1, "status": "paid"}, {"id": 2, "status": "pending"}]
print(transform(data))
print("name preserved:", transform.__name__)
print("doc preserved:", transform.__doc__)

import functools
import time

def retry(times=3, delay=0.5, exceptions=(ConnectionError,)):
    """Factory: returns a decorator that retries on the given exceptions."""
    def decorator(func):
        @functools.wraps(func)
        def wrapper(*args, **kwargs):
            last_exc = None
            for attempt in range(1, times + 1):
                try:
                    return func(*args, **kwargs)
                except exceptions as exc:
                    last_exc = exc
                    print(f"[retry] {func.__name__} attempt {attempt} failed: {exc}")
                    if attempt < times:
                        time.sleep(delay)
            raise last_exc            # exhausted retries -> re-raise
        return wrapper
    return decorator

_calls = {"n": 0}

@retry(times=3, delay=0)
def fetch(url):
    _calls["n"] += 1
    if _calls["n"] < 3:
        raise ConnectionError("temporary network error")
    return f"data from {url}"

print(fetch("http://api/orders"))
print("total attempts:", _calls["n"])

import functools

# 1) Memoize an expensive, pure lookup (e.g., a dimension lookup)
call_count = {"n": 0}

@functools.lru_cache(maxsize=128)
def region_for_zip(zip_code):
    call_count["n"] += 1          # simulates an expensive DB/API call
    return "WEST" if zip_code.startswith("9") else "EAST"

print(region_for_zip("90210"))
print(region_for_zip("90210"))   # served from cache, no recompute
print(region_for_zip("10001"))
print("actual computations:", call_count["n"])
print("cache:", region_for_zip.cache_info())

# 2) A registry decorator: collect tasks by name
TASKS = {}

def task(name):
    def decorator(func):
        TASKS[name] = func
        return func               # return original unchanged; just register
    return decorator

@task("ingest")
def ingest():
    return "ingesting"

@task("clean")
def clean():
    return "cleaning"

print("registered:", sorted(TASKS))
print(TASKS["ingest"]())

